3.  **`src/app/game/game_logic_service.c`**: A new function is added to implement the core logic.
    ```c
    #include <time.h>
    #include "game_logic_service.h"
    #include "player_state.h"
    #include "models/tf_task.h"

    #define COMBO_WINDOW_SECONDS 600 // 10 minutes
    #define MAX_COMBO_MULTIPLIER 1.5f

    void game_logic_service_process_task_completion(TF_Task* completed_task) {
        PlayerState* state = get_current_player_state(); // Assumes a function to get state
        time_t now = time(NULL);

        if ((now - state->last_task_completion_timestamp) <= COMBO_WINDOW_SECONDS) {
            state->combo_count++;
        } else {
            state->combo_count = 1; // Reset or start combo
        }
        state->last_task_completion_timestamp = now;

        float bonus_multiplier = 0.1f * (state->combo_count - 1);
        if (bonus_multiplier > 0.5f) { bonus_multiplier = 0.5f; }

        int base_xp = completed_task->xp_value;
        int bonus_xp = (int)(base_xp * bonus_multiplier);

        player_state_add_xp(state, base_xp + bonus_xp); // Assumes function to add XP
    }
    ```

4.  **`src/app/tasks/task_service.c`**: The task completion function is modified to call the new logic.
    ```c
    // In a function like task_service_complete_task(TF_Task* task)
    // ... after task is successfully marked complete ...
    #include "game_logic_service.h"

    game_logic_service_process_task_completion(task);
    // ... rest of the function
    ```
